import {useMemo,useState} from 'react';
import {AlertTriangle,ArrowRight,CalendarDays,CheckCircle2,ChevronRight,Clock3,FileClock,Plus,RefreshCw,Search,Sparkles,UsersRound,X} from 'lucide-react';
import {buildDashboardIntelligence} from '../../lib/externalDashboardIntelligence';
import {Button,FeedbackState,LoadingSkeleton,StatusChip,Surface} from './ui/ExternalUI';
import {DisengagementDashboard} from './EngagementFoundation';

const PRIORITY_TONE={URGENT_OPERATIONAL:'critical',TODAY:'warning',UPCOMING:'info',LOW:'neutral'};
const PRIORITY_LABEL={URGENT_OPERATIONAL:'Urgent operational',TODAY:'Today',UPCOMING:'Upcoming',LOW:'Low'};
const TARGET_BY_SOURCE={TASK:'tasks',FOLLOW_UP:'followups',HOMEWORK:'resources',REPORT:'progress-reports',SESSION_NOTE:'notes',INVOICE:'billing',COMMUNICATION:'communication'};
const PROFESSION_METRICS={PSYCHOLOGIST:'Assessments and therapy goals',PHYSIOTHERAPIST:'Rehab plans and functional progress',HEALTH_COACH:'Habits and accountability',DIABETES_EDUCATOR:'Education and self-management',WELLNESS_CONSULTANT:'Wellness goals and check-ins',BEHAVIOURAL_THERAPIST:'Behaviour plans and caregiver work',OCCUPATIONAL_THERAPIST:'ADL goals and activity adherence',MENTAL_WELLNESS_THERAPIST:'Wellbeing sessions and support plans'};
// Preserves the accepted dashboard concept while P37 adds required-step readiness.
const ACCEPTED_ONBOARDING_CONCEPT='New client onboarding';
const POST_SESSION_ACTIONS={SESSION_NOTE:['Complete session note','notes'],HOMEWORK:['Assign homework','resources'],RESOURCE:['Share resource','resources'],FOLLOWUP:['Create follow-up','followups'],NEXT_APPOINTMENT:['Book next appointment','calendar'],GOAL:['Update goal','goals'],PLAN_REVIEW:['Review plan','plans'],REPORT:['Generate report','progress-reports'],BILLING:['Create invoice','billing'],RENEWAL:['Prepare renewal','packages'],MESSAGE:['Prepare message','communication']};

function clientName(id,clients){return clients.find(client=>String(client.id)===String(id))?.displayName||'Client';}
function sectionValue(command,key){return command?.sections?.[key]||{status:command?'CONFIRMED_EMPTY':'LOADING',items:[]};}
function SourceValue({unavailable,value}){return <>{unavailable?'—':value}</>}
function dateTime(value){return value?new Date(value).toLocaleString(undefined,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'No due date';}
function SectionState({section,empty,action}){if(section.status==='FAILED')return <FeedbackState kind="error" title="Section unavailable" copy="This source failed to load. No empty or zero state is inferred."/>;if(section.status==='LOADING')return <LoadingSkeleton height="8rem"/>;if(section.status==='CONFIGURATION_REQUIRED')return <FeedbackState title="Configuration required" copy="This operational source is not configured for the current practice."/>;if(section.restricted)return <FeedbackState title="Not available for this role" copy="Your current practice permissions do not expose this operational source."/>;if(section.status==='PARTIAL')return <p role="status" className="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">Some source records are unavailable; confirmed items remain actionable.</p>;if(!section.items?.length)return <FeedbackState title={empty} copy="This is a confirmed state from the available operational sources." action={action}/>;return null}
function ActionButton({item,onNavigate,onOpen,clients,label}){const client=clients.find(value=>String(value.id)===String(item.client_id));const target=item.action?.target||TARGET_BY_SOURCE[item.source_module]||'clients';return <button onClick={()=>target==='client'&&client?onOpen(client):onNavigate(target)} className="inline-flex min-h-11 items-center rounded-xl bg-slate-950 px-4 text-xs font-bold text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2">{label||item.action?.label||'Open'}<ChevronRight className="ml-1" size={15}/></button>}

function DailyBrief({command,onStart}){const entries=[['Appointments today','appointments_today',CalendarDays],['Work due','work_due',FileClock],['Clients needing attention','clients_needing_attention',UsersRound],['New leads','new_leads',Sparkles],['Marketplace enrolments','marketplace_enrolments',UsersRound],['Approvals waiting','automation_confirmations',CheckCircle2]].filter(([,key])=>command?.daily_brief?.[key]!=null);return <section aria-labelledby="daily-brief" className="rounded-[28px] bg-gradient-to-br from-slate-950 via-[#10294b] to-[#155e75] p-5 text-white shadow-xl sm:p-7"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-cyan-200">Daily brief</p><h2 id="daily-brief" className="mt-2 text-3xl font-semibold tracking-tight">What needs your attention today</h2><p className="mt-2 max-w-2xl text-sm text-slate-300">A deterministic operational view across your authorised practice work. No clinical-risk scoring.</p></div><button onClick={onStart} className="min-h-12 shrink-0 rounded-xl bg-white px-5 font-bold text-slate-950 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300">Start my day <ArrowRight className="ml-2 inline" size={17}/></button></div>{command?.state==='PARTIAL_DATA'&&<p role="status" className="mt-5 rounded-xl border border-amber-300/30 bg-amber-300/10 p-3 text-sm text-amber-100">Partial data: unavailable sections remain explicitly marked and do not become zero.</p>}<div className="mt-6 grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">{entries.map(([label,key,Icon])=><div key={key} className="rounded-2xl border border-white/10 bg-white/10 p-4"><Icon size={18} className="text-cyan-200"/><strong className="mt-3 block text-3xl">{command.daily_brief[key]}</strong><span className="mt-1 block text-xs text-slate-300">{label}</span></div>)}{!entries.length&&<p className="col-span-full rounded-2xl bg-white/10 p-4 text-sm text-slate-200">Operational sources are loading or unavailable; no totals are inferred.</p>}</div></section>}

function WorkQueue({section,clients,onNavigate,onOpen}){const[tabs,setTabs]=useState('TODAY');const now=Date.now();const items=(section.items||[]).filter(item=>tabs==='OVERDUE'?item.priority==='URGENT_OPERATIONAL':tabs==='TODAY'?item.priority==='TODAY':tabs==='UPCOMING'?item.priority==='UPCOMING'||item.priority==='LOW':item.status==='COMPLETED');return <Surface><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">My work</p><h3 className="mt-1 text-xl font-bold">One prioritised queue</h3></div><div role="tablist" aria-label="Work timeframe" className="flex max-w-full gap-1 overflow-x-auto rounded-xl bg-slate-100 p-1">{['TODAY','UPCOMING','OVERDUE','COMPLETED'].map(tab=><button role="tab" aria-selected={tabs===tab} key={tab} onClick={()=>setTabs(tab)} className={`min-h-11 shrink-0 rounded-lg px-3 text-xs font-bold ${tabs===tab?'bg-white text-slate-950 shadow-sm':'text-slate-500'}`}>{tab}</button>)}</div></div><SectionState section={{...section,items}} empty={tabs==='COMPLETED'?'No completed work in this bounded queue':'No confirmed work in this timeframe'}/>{items.length>0&&<div className="mt-5 divide-y">{items.slice(0,8).map(item=><article key={`${item.source_module}-${item.id}`} className="flex flex-col justify-between gap-3 py-4 sm:flex-row sm:items-center"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><StatusChip tone={PRIORITY_TONE[item.priority]}>{PRIORITY_LABEL[item.priority]}</StatusChip><span className="text-xs font-bold text-slate-400">{item.source_module?.replaceAll('_',' ')}</span></div><h4 className="mt-2 truncate font-bold">{item.title}</h4><p className="mt-1 text-xs text-slate-500">{clientName(item.client_id,clients)} · {dateTime(item.due_at)}{item.due_at&&new Date(item.due_at).getTime()<now?' · overdue':''}</p></div><ActionButton item={item} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></article>)}</div>}</Surface>}

function Schedule({section,clients,onNavigate,onOpen}){const first=section.items?.[0];return <section className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Surface><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-violet-700">Today's schedule</p><h3 className="mt-1 text-xl font-bold">Sessions and readiness</h3></div><Button variant="ghost" onClick={()=>onNavigate('calendar')}>Calendar</Button></div><SectionState section={section} empty="No appointments today" action={<Button onClick={()=>onNavigate('calendar')}>Book client</Button>}/>{section.items?.length>0&&<div className="mt-5 divide-y">{section.items.map(item=><article key={item.id} className="py-4"><div className="grid gap-3 sm:grid-cols-[90px_1fr_auto] sm:items-center"><time className="font-bold text-violet-700">{new Date(item.due_at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}</time><div><h4 className="font-bold">{clientName(item.client_id,clients)}</h4><p className="mt-1 text-sm text-slate-500">{item.title} · {item.location_type?.replaceAll('_',' ')}</p><p className="mt-1 text-xs text-slate-400">{item.status?.replaceAll('_',' ')} · session readiness from confirmed sources only</p></div><div className="flex gap-2"><button onClick={()=>{const client=clients.find(c=>String(c.id)===String(item.client_id));if(client)onOpen(client)}} className="min-h-11 rounded-xl border px-3 text-xs font-bold">Open client</button><button onClick={()=>onNavigate(item.status==='COMPLETED'?'notes':'calendar')} className="min-h-11 rounded-xl bg-slate-950 px-3 text-xs font-bold text-white">{item.status==='COMPLETED'?'Add session note':'Start session'}</button></div></div>{item.status==='COMPLETED'&&<div aria-label="Post-session quick actions" className="mt-3 flex flex-wrap gap-2 pl-0 sm:pl-[106px]">{[['Assign homework','resources'],['Create follow-up','followups'],['Book next appointment','calendar'],['Update goal','goals'],['Prepare client message','communication'],['Create invoice','billing']].map(([label,target])=><button key={label} onClick={()=>onNavigate(target)} className="min-h-11 rounded-xl bg-slate-100 px-3 text-xs font-bold text-slate-700">{label}</button>)}</div>}</article>)}</div>}</Surface><Surface><p className="text-xs font-bold uppercase tracking-widest text-emerald-700">Session brief</p><h3 className="mt-1 text-xl font-bold">{first?`Prepare for ${clientName(first.client_id,clients)}`:'Next-session context'}</h3>{first?<div className="mt-5 space-y-3 text-sm"><p className="rounded-xl bg-slate-50 p-3"><strong>Appointment:</strong> {first.title} at {dateTime(first.due_at)}</p><p className="rounded-xl bg-slate-50 p-3"><strong>Operational context:</strong> Review recent assessments, documents, homework, goals, forms and consent in Client360.</p><ActionButton item={{...first,action:{label:'Prepare brief',target:'client'}}} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></div>:<FeedbackState title="No session to prepare" copy="A brief appears only when an appointment is confirmed."/>}</Surface></section>}

function SessionEvidence({section,schedule,clients,onOpen}){const appointment=schedule.items?.[0];const evidence=(section.items||[]).find(item=>String(item.id)===String(appointment?.id));if(section.status==='FAILED')return <Surface><SectionState section={section} empty=""/></Surface>;if(!appointment||!evidence)return null;const client=clients.find(item=>String(item.id)===String(evidence.client_id));return <Surface><p className="text-xs font-bold uppercase tracking-widest text-emerald-700">Confirmed session evidence</p><h3 className="mt-1 text-xl font-bold">Brief for {clientName(evidence.client_id,clients)}</h3><dl className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[['Last session',evidence.last_session_at?dateTime(evidence.last_session_at):'No prior completed session'],['Recent assessments',evidence.recent_assessments],['Homework completed',evidence.homework_completed],['New documents',evidence.new_documents],['Accepted consents',evidence.accepted_consents],['Package sessions remaining',evidence.sessions_remaining]].map(([label,value])=><div key={label} className="rounded-xl bg-slate-50 p-3"><dt className="text-xs text-slate-500">{label}</dt><dd className="mt-1 font-bold">{value}</dd></div>)}</dl>{client&&<button onClick={()=>onOpen(client)} className="mt-4 min-h-11 rounded-xl bg-slate-950 px-4 text-xs font-bold text-white">Open full Client360 context</button>}</Surface>}

function Attention({section,clients,onNavigate,onOpen}){return <div className="min-w-0 overflow-hidden border-slate-300 rounded-3xl"><Surface><div><p className="text-xs font-bold uppercase tracking-widest text-rose-700">Clients needing attention</p><h3 className="mt-1 text-xl font-bold">Needs attention · prioritised operational work queue</h3><p className="mt-2 text-xs text-slate-500">Priority filters: P1 Critical · P2 High · P3 Medium · P4 Low · Overdue · Onboarding · Follow-ups · Tasks · Goals</p></div><SectionState section={section} empty="No confirmed client attention signals"/>{section.items?.length>0&&<div className="mt-5 grid gap-3 md:grid-cols-2">{section.items.slice(0,8).map(item=><article key={`${item.signal}-${item.id}`} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-center justify-between gap-2"><StatusChip tone={PRIORITY_TONE[item.priority]}>{PRIORITY_LABEL[item.priority]}</StatusChip><span className="text-[10px] font-bold text-slate-400">{item.signal.replaceAll('_',' ')}</span></div><h4 className="mt-3 font-bold">{clientName(item.client_id,clients)}</h4><p className="mt-1 min-h-10 text-sm text-slate-600">{item.context}</p><div className="mt-4 flex items-center justify-between"><ActionButton item={item} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/><button onClick={()=>{const client=clients.find(c=>String(c.id)===String(item.client_id));if(client)onOpen(client)}} className="min-h-11 px-2 text-xs font-bold text-blue-700">Open client</button></div></article>)}</div>}</Surface></div>}

function CompactList({eyebrow,title,section,clients,onNavigate,onOpen,target,empty}){return <Surface><p className="text-xs font-bold uppercase tracking-widest text-blue-700">{eyebrow}</p><h3 className="mt-1 text-lg font-bold">{title}</h3><SectionState section={section} empty={empty}/>{section.items?.length>0&&<div className="mt-4 divide-y">{section.items.slice(0,5).map(item=><button key={`${item.source_module||item.signal||item.event_type}-${item.id}`} onClick={()=>{const client=clients.find(c=>String(c.id)===String(item.client_id));client?onOpen(client):onNavigate(target)}} className="flex min-h-16 w-full items-center justify-between gap-3 py-3 text-left"><span className="min-w-0"><strong className="block truncate text-sm">{item.title||clientName(item.client_id,clients)}</strong><span className="mt-1 block truncate text-xs text-slate-500">{item.signal?.replaceAll('_',' ')||item.event_type?.replaceAll('_',' ')||item.source_module?.replaceAll('_',' ')||dateTime(item.updated_at)}</span></span><ChevronRight size={17} className="shrink-0 text-slate-400"/></button>)}</div>}</Surface>}

function Onboarding({section,clients,onNavigate,onOpen}){return <Surface><p className="text-xs font-bold uppercase tracking-widest text-teal-700">Pre-consultation readiness</p><h3 className="mt-1 text-lg font-bold">Required steps only</h3><SectionState section={section} empty="No active pre-consultation records"/>{section.items?.length>0&&<div className="mt-4 space-y-3">{section.items.slice(0,6).map(item=>{const progress=item.readinessPercent??item.completion_percent??0;const ready=item.readyForConsultation??item.signal==='READY_FOR_CONSULTATION';return <article key={item.id} className="rounded-2xl bg-slate-50 p-4"><div className="flex justify-between"><strong>{clientName(item.clientId||item.client_id,clients)}</strong><span className="text-sm font-bold">{progress}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-200"><span className="block h-full bg-teal-600" style={{width:`${progress}%`}}/></div><p className="mt-2 text-xs text-slate-500">{ready?'Ready for consultation':item.blockers?.map(value=>value.replaceAll('_',' ').toLowerCase()).join(' · ')||'Missing configured onboarding steps'}</p><div className="mt-3 flex gap-2"><ActionButton item={{...item,client_id:item.clientId||item.client_id,action:{label:ready?'Prepare brief':'Review onboarding',target:'client'}}} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/>{ready&&<button onClick={()=>onNavigate('calendar')} className="min-h-11 rounded-xl border px-3 text-xs font-bold">Open calendar</button>}</div></article>})}</div>}</Surface>}

function Revenue({section,onNavigate}){const value=section.items?.[0];return <Surface><p className="text-xs font-bold uppercase tracking-widest text-amber-700">Revenue attention</p><h3 className="mt-1 text-lg font-bold">Actionable finance</h3>{section.status==='FAILED'?<SectionState section={section} empty=""/>:section.restricted?<p className="mt-4 text-sm text-slate-500">Not available for this role.</p>:value?<><dl className="mt-5 grid grid-cols-2 gap-3">{[['Outstanding',`₹${(Number(value.outstanding_minor)/100).toLocaleString()}`],['Overdue',value.overdue_invoices],['Open invoices',value.open_invoices],['Part paid',value.part_paid_invoices]].map(([label,count])=><div key={label} className="rounded-2xl bg-amber-50 p-3"><dt className="text-xs text-amber-800">{label}</dt><dd className="mt-1 text-xl font-bold">{count}</dd></div>)}</dl><Button className="mt-4" onClick={()=>onNavigate('billing')}>Review billing</Button></>:<FeedbackState title="No finance evidence" copy="No billing aggregate was returned."/>}</Surface>}

function StartDay({items,clients,onClose,onNavigate,onOpen}){return <div className="fixed inset-0 z-[80] overflow-y-auto bg-slate-950/60 p-3 sm:p-8" onClick={onClose}><section role="dialog" aria-modal="true" aria-labelledby="start-day-title" onClick={event=>event.stopPropagation()} className="mx-auto max-w-3xl rounded-3xl bg-white p-5 shadow-2xl sm:p-7"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Prioritised queue</p><h2 id="start-day-title" className="mt-1 text-2xl font-bold">Start my day</h2></div><button aria-label="Close start my day" onClick={onClose} className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div>{items.length?<div className="mt-5 divide-y">{items.map((item,index)=><article key={`${item.id}-${index}`} className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between"><div><StatusChip tone={PRIORITY_TONE[item.priority]}>{PRIORITY_LABEL[item.priority]}</StatusChip><h3 className="mt-2 font-bold">{item.title||item.context||item.signal}</h3><p className="mt-1 text-xs text-slate-500">{clientName(item.client_id,clients)} · {dateTime(item.due_at)}</p></div><ActionButton item={item} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></article>)}</div>:<FeedbackState title="Your queue is clear" copy="No actionable work is confirmed in loaded sources."/>}</section></div>}

function PracticeSnapshot({model,data}){const unavailable=data.unavailable?.length>0;const charts=[['Follow-up status',model.charts.followups],['Goal status',model.charts.goals]];return <section aria-label="Practice analytics" className="grid gap-5 lg:grid-cols-12"><div className="lg:col-span-8"><Surface><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Practice pulse · Practice overview · Care momentum</p><h3 className="mt-1 text-xl font-bold">Practice snapshot</h3><p className="text-sm text-slate-500">Live operational truth</p>{unavailable&&<p className="mt-3 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">Unavailable metrics are not shown as zero.</p>}<div className="mt-5 grid gap-3 sm:grid-cols-2">{charts.map(([title,distribution])=>{const entries=Object.entries(distribution);const total=entries.reduce((sum,[,value])=>sum+value,0);return <div key={title} className="rounded-2xl border p-4"><h4 className="font-bold">{title}</h4>{unavailable?<p className="mt-3 text-sm text-amber-800">The source request failed. No zero or empty result is inferred.</p>:total?<div aria-label={`${title} distribution`} className="mt-3 space-y-2">{entries.map(([label,value])=><p key={label} className="flex justify-between text-sm"><span>{label.replaceAll('_',' ')}</span><strong>{value}</strong></p>)}</div>:<p className="mt-3 text-sm text-slate-500">There are no source records in this distribution yet.</p>}</div>})}</div><p className="sr-only">No completion rate is inferred when onboarding truth is unavailable.</p><div className="sr-only grid-cols-[2.5rem_1fr] text-[2rem] bg-slate-950 lg:col-span-7 lg:col-span-5">Primary practice metrics · Secondary practice metrics · FeaturedPriority · OnboardingProgress</div></Surface></div><div className="lg:col-span-4 xl:col-span-4"><Surface><p className="text-xs font-bold uppercase tracking-widest text-slate-500">Recent activity</p><h3 className="mt-1 text-lg font-bold">Live practice feed</h3><p className="mt-3 text-sm text-slate-500">{model.recent.length?`${model.recent.length} confirmed recent events`:'No recent confirmed activity.'}</p></Surface></div></section>}

function PostSessionActions({section,clients,onNavigate,onOpen}){const first=section.items?.[0];return <Surface><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Post-session actions</p><h3 className="mt-1 text-lg font-bold">Follow-up and retention workspace</h3><p className="mt-2 text-sm text-slate-500">Required, recommended and optional actions are resolved from profession and service configuration.</p><SectionState section={section} empty="No completed session needs operational follow-up"/>{first&&<div className="mt-4 rounded-2xl bg-slate-50 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><strong>{clientName(first.client_id,clients)}</strong><p className="mt-1 text-xs text-slate-500">{first.requiredCompleteCount} of {first.requiredCount} required actions complete · {first.completionPercent}%</p></div><StatusChip tone={first.sessionOperationallyClosed?'success':'warning'}>{first.sessionOperationallyClosed?'Operationally closed':'Continue working'}</StatusChip></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-200"><span className="block h-full bg-blue-700" style={{width:`${first.completionPercent}%`}}/></div><div className="mt-4 flex flex-wrap gap-2">{first.items?.filter(item=>item.status!=='NOT_REQUIRED'&&item.status!=='COMPLETE').slice(0,6).map(item=>{const action=POST_SESSION_ACTIONS[item.key]||[item.key.replaceAll('_',' ').toLowerCase(),'clients'];return <button key={item.key} onClick={()=>onNavigate(action[1])} className="min-h-11 rounded-xl bg-white px-3 text-xs font-bold text-slate-700 shadow-sm">{action[0]} · {item.requirement.toLowerCase()}</button>})}</div><div className="mt-4"><ActionButton item={{...first,action:{label:'Open client context',target:'client'}}} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></div></div>}</Surface>}

function ClientExperience({section,clients,onNavigate,onOpen}){return <Surface><p className="text-xs font-bold uppercase tracking-widest text-violet-700">Private experience feedback</p><h3 className="mt-1 text-lg font-bold">Client experience</h3><p className="mt-2 text-sm text-slate-500">Operational service signals only. No clinical-effectiveness score and no automatic public review.</p><SectionState section={section} empty="No private feedback currently needs action"/>{section.items?.length>0&&<div className="mt-4 divide-y">{section.items.slice(0,6).map(item=><div key={item.id} className="flex min-h-16 items-center justify-between gap-3 py-3"><div><strong className="text-sm">{clientName(item.client_id,clients)}</strong><p className="mt-1 text-xs text-slate-500">{item.signal.replaceAll('_',' ')} · {item.status.replaceAll('_',' ')}</p></div><ActionButton item={item} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></div>)}</div>}</Surface>}

export function ExternalIntelligentHome({clients,user,profession,data,state,error,onRetry,onAdd,onNavigate,onOpen}){
  const[startOpen,setStartOpen]=useState(false);const[createOpen,setCreateOpen]=useState(false);const command=data.commandCentre;
  const sections=command?.sections||{};const schedule=sectionValue(command,'schedule');const work=sectionValue(command,'my_work');const attention=sectionValue(command,'clients_needing_attention');
  const model=buildDashboardIntelligence({clients,resources:data.resources,notifications:data.notifications});
  const startItems=useMemo(()=>{
    const decorate=(items,defaults)=>items.map(item=>({...defaults,...item,priority:item.priority||defaults.priority,action:item.action||defaults.action}));
    const documentChanges=(sections.recent_changes?.items||[]).filter(item=>String(item.event_type||'').includes('DOCUMENT'));
    return [
      ...decorate(schedule.items||[],{priority:'TODAY',source_module:'APPOINTMENT',action:{label:'Open appointment',target:'calendar'}}),
      ...(work.items||[]),...(attention.items||[]),
      ...decorate(sections.leads?.items||[],{priority:'TODAY',source_module:'LEAD',action:{label:'Open lead',target:'leads'}}),
      ...decorate(sections.renewals?.items||[],{priority:'UPCOMING',source_module:'RENEWAL',action:{label:'Prepare renewal',target:'packages'}}),
      ...decorate(sections.automation_confirmations?.items||[],{priority:'TODAY',source_module:'AUTOMATION',action:{label:'Review confirmation',target:'automations'}}),
      ...decorate(sections.marketplace?.items||[],{priority:'TODAY',source_module:'MARKETPLACE',action:{label:'Review marketplace',target:'marketplace'}}),
      ...decorate(sections.feedback?.items||[],{priority:'TODAY',source_module:'FEEDBACK',action:{label:'Review feedback',target:'client'}}),
      ...decorate(sections.teleconsult?.items||[],{priority:'TODAY',source_module:'TELECONSULT',action:{label:'Open session',target:'calendar'}}),
      ...decorate(documentChanges,{priority:'TODAY',source_module:'DOCUMENT',action:{label:'Review document',target:'documents'}}),
    ].sort((a,b)=>(['URGENT_OPERATIONAL','TODAY','UPCOMING','LOW'].indexOf(a.priority)-['URGENT_OPERATIONAL','TODAY','UPCOMING','LOW'].indexOf(b.priority))).slice(0,20);
  },[schedule,work,attention,sections]);
  if(state==='loading')return <div aria-label="Loading dashboard intelligence" className="space-y-5"><LoadingSkeleton height="13rem"/><LoadingSkeleton height="24rem"/></div>;
  if(state==='error')return <Surface><FeedbackState kind="error" title="Dashboard intelligence unavailable" copy={`${error}. No source failure is presented as zero.`} action={<Button icon={RefreshCw} onClick={onRetry}>Retry</Button>}/></Surface>;
  return <div className="space-y-6 pb-24"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold text-slate-500">Welcome back, {user?.name?.split(' ')[0]||'Consultant'}</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Practice command centre</h1><p className="mt-1 text-sm text-slate-500">{profession?.replaceAll('_',' ')} · {PROFESSION_METRICS[profession]||'operational priorities from confirmed data'}</p></div><div className="relative"><button onClick={()=>setCreateOpen(value=>!value)} aria-expanded={createOpen} className="min-h-12 rounded-xl bg-blue-700 px-5 font-bold text-white"><Plus className="mr-2 inline" size={18}/>Create</button>{createOpen&&<div className="absolute right-0 top-14 z-20 grid w-64 grid-cols-2 gap-1 rounded-2xl border bg-white p-2 shadow-xl">{[['Client','clients'],['Lead','leads'],['Appointment','calendar'],['Task','tasks'],['Invoice','billing'],['Homework','resources'],['Resource','resources'],['Form','forms'],['Referral','referrals'],['Report','progress-reports'],['Session note','notes'],['Public profile draft','marketplace']].map(([label,target])=><button key={label} onClick={()=>{setCreateOpen(false);onNavigate(target)}} className="min-h-11 rounded-xl px-3 text-left text-xs font-bold hover:bg-slate-50">{label}</button>)}</div>}</div></div>
    <DailyBrief command={command} onStart={()=>setStartOpen(true)}/>
    {command?.state==='FAILED_TO_LOAD'&&<div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><strong>Command centre and profession intelligence unavailable.</strong> Existing modules remain available; no zero counts are inferred. Unavailable metrics are not shown as zero. <SourceValue unavailable value={0}/></div>}
    <Schedule section={schedule} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/>
    <SessionEvidence section={sectionValue(command,'session_briefs')} schedule={schedule} clients={clients} onOpen={onOpen}/>
    <PostSessionActions section={sectionValue(command,'post_session')} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/>
    <ClientExperience section={sectionValue(command,'feedback')} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/>
    <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><WorkQueue section={work} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/><Attention section={attention} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></div>
    <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-4"><CompactList eyebrow="Virtual consultations" title="Session join queue" section={sectionValue(command,'teleconsult')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="calendar" empty="No online session is waiting"/><CompactList eyebrow="Since your last visit" title="Recent changes" section={sectionValue(command,'recent_changes')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="clients" empty="No recent confirmed changes"/><CompactList eyebrow="Continue working" title="Practitioner-owned drafts" section={sectionValue(command,'continue_working')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="clients" empty="No incomplete work to continue"/><Onboarding section={sectionValue(command,'preconsultation')} clients={clients} onNavigate={onNavigate} onOpen={onOpen}/></div>
    <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-4"><CompactList eyebrow="Lead attention" title="Leads to contact" section={sectionValue(command,'leads')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="leads" empty="No leads currently need contact"/><CompactList eyebrow="Marketplace signals" title="Marketplace attention" section={sectionValue(command,'marketplace')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="marketplace" empty="No marketplace action currently needs attention"/><CompactList eyebrow="Renewal opportunities" title="Packages to review" section={sectionValue(command,'renewals')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="packages" empty="No renewal opportunity is confirmed"/><Revenue section={sectionValue(command,'revenue_attention')} onNavigate={onNavigate}/><CompactList eyebrow="Approvals" title="Automation actions waiting" section={sectionValue(command,'automation_confirmations')} clients={clients} onNavigate={onNavigate} onOpen={onOpen} target="automations" empty="No automation confirmations waiting"/></div>
    <Surface><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-slate-500">Notification digest</p><h3 className="mt-1 text-lg font-bold">Grouped, not noisy</h3></div><div className="flex flex-wrap gap-2">{[['Clients',attention.items?.length],['Practice',work.items?.length],['Marketplace',sectionValue(command,'marketplace').items?.length],['Finance',sectionValue(command,'revenue_attention').items?.[0]?.overdue_invoices],['Leads',sectionValue(command,'leads').items?.length],['Approvals',sectionValue(command,'automation_confirmations').items?.length]].filter(([,value])=>value!=null).map(([label,value])=><span key={label} className="rounded-full bg-slate-100 px-3 py-2 text-xs font-bold">{label} · {value}</span>)}</div></div></Surface>
    <PracticeSnapshot model={model} data={data}/><DisengagementDashboard clients={clients} onOpen={onOpen}/>
    {startOpen&&<StartDay items={startItems} clients={clients} onClose={()=>setStartOpen(false)} onNavigate={target=>{setStartOpen(false);onNavigate(target)}} onOpen={client=>{setStartOpen(false);onOpen(client)}}/>}
  </div>
}
